export const CSV_EAN='CLIENTE_ID;PRODUCTO_ID;TIPO_CODIGO;CODIGO;CANTIDAD\r\nBELIA;000123;EAN13;0012345678901;12\r\nAVIBM;000007;DUN14;00012345678901;\r\nPENDIENTE;000008;EAN13;0012345678901;0\r\n';
const HEAD=['POSICION_ID','POSICION_COD','BODEGA','CALLE','COLUMNA','NIVEL','PROFUNDIDAD','COD_CLIENTE','STATUS_OCUPACION','TIPO_POS','ALMACEN','CIUDAD','POS_LOCKEADA','ORDEN_PICKING','ORDEN_LOCATOR','LARGO','ANCHO','ALTO','VOLUMEN','PESO','PICKING','ABASTECIBLE','BESTFIT','BESTFIT_PERMITE_ABAST','PCJ_OCUPACION','CATEGORIA'];
export function csvPosiciones(rows=[{COD_CLIENTE:'BELIA'},{COD_CLIENTE:'OTRO'},{CIUDAD:'GUAYAQUIL',ALMACEN:'CD_GUAYAQUIL1',COD_CLIENTE:'ALU'}]){
 return [HEAD.join(';'),...rows.map(r=>{const row={...Object.fromEntries(HEAD.map(k=>[k,'0'])),POSICION_ID:'00001',POSICION_COD:'A-01-01',BODEGA:'B1',CALLE:'A',COLUMNA:'01',NIVEL:'01',PROFUNDIDAD:'',COD_CLIENTE:'',STATUS_OCUPACION:'LIBRE',TIPO_POS:'RACK',ALMACEN:'CD_QUITO1',CIUDAD:'QUITO',LARGO:'120',ANCHO:'100',ALTO:'200',...r};return HEAD.map(k=>row[k]).join(';');})].join('\r\n')+'\r\n';
}
